import type { CodegenConfig } from "@graphql-codegen/cli";

// Typed documents for the curated public operations in pkg/graphql/public.
// String mode emits each document as a typed string, so the package has no
// graphql runtime dependency.
const config: CodegenConfig = {
  schema: "../pkg/graphql/schema.graphql",
  documents: ["../pkg/graphql/public/**/*.graphql"],
  ignoreNoDocuments: false,
  generates: {
    "src/generated/graphql.ts": {
      plugins: [
        {
          add: {
            content:
              "/* Code generated by make graphql-sdk-ts from pkg/graphql/public. DO NOT EDIT. */",
          },
        },
        "typescript-operations",
        "typed-document-node",
      ],
      config: {
        documentMode: "string",
        // Type and document names match the schema and operation names
        // exactly (DeleteDVRMutation), as in the Go and Python SDKs.
        namingConvention: "keep",
        enumType: "string-literal",
        futureProofEnums: true,
        futureProofUnions: true,
        // The client sends documents unchanged, so __typename exists only
        // where an operation selects it.
        skipTypename: true,
        avoidOptionals: { field: true, inputValue: false, object: true, defaultValue: false },
        strictScalars: true,
        scalars: {
          ID: "string",
          Time: "string",
          JSON: "unknown",
          Currency: "string",
          Money: "string",
        },
        useTypeImports: true,
        dedupeFragments: true,
        // Marks each document constant side-effect free, so a bundle that
        // imports one document (the player's ResolveViewerEndpoint) drops the
        // others.
        pureMagicComment: true,
      },
    },
  },
};

export default config;
